import java.util.concurrent.ConcurrentHashMap

fun bad(map: ConcurrentHashMap<String, String>, key: String, value: String) {
    if (!map.containsKey(key)) { // bad: non-atomic check-then-act
        map.put(key, value)
    }
}

import java.util.concurrent.ConcurrentHashMap

class Cache {
    private val store = ConcurrentHashMap<String, String>()

    fun put(key: String, value: String) {
        if (!store.containsKey(key)) { // bad: race condition between check and put
            store.put(key, value)
        }
    }
}

import java.util.concurrent.ConcurrentHashMap

fun good(map: ConcurrentHashMap<String, String>, key: String, value: String) {
    map.putIfAbsent(key, value) // ok: atomic operation
}

import java.util.concurrent.ConcurrentHashMap

class Cache {
    private val store = ConcurrentHashMap<String, List<String>>()
    fun getOrCreate(key: String) = store.computeIfAbsent(key) { emptyList() } // ok: atomic
}

fun good(map: HashMap<String, String>, key: String, value: String) {
    if (!map.containsKey(key)) {
        map.put(key, value) // ok: regular (non-concurrent) map
    }
}
